-- A blank service UUID is generated by the Connector, which reports it in its
-- authenticated inventory snapshots. A declared service_id always wins; without
-- one, the Connector's own snapshot is the authority.
ALTER TABLE farm.spoolman_connector_settings ADD COLUMN observed_service_id uuid;

UPDATE farm.spoolman_connector_settings c
SET observed_service_id = (s.snapshot->>'serviceId')::uuid
FROM farm.connector_inventory_snapshots s
WHERE s.farm_id = c.farm_id AND s.agent_id = c.agent_id AND c.configured
  AND s.snapshot->>'serviceId' ~* '^[0-9a-f]{8}-([0-9a-f]{4}-){3}[0-9a-f]{12}$';

-- The telemetry writer gets no privilege on settings.
CREATE FUNCTION farm.record_observed_spoolman_service_id()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
  IF NEW.snapshot->>'serviceId' ~* '^[0-9a-f]{8}-([0-9a-f]{4}-){3}[0-9a-f]{12}$' THEN
    UPDATE farm.spoolman_connector_settings
    SET observed_service_id = (NEW.snapshot->>'serviceId')::uuid
    WHERE farm_id = NEW.farm_id AND agent_id = NEW.agent_id AND configured
      AND observed_service_id IS DISTINCT FROM (NEW.snapshot->>'serviceId')::uuid;
  END IF;
  RETURN NULL;
END;
$$;
REVOKE ALL ON FUNCTION farm.record_observed_spoolman_service_id() FROM PUBLIC;
CREATE TRIGGER connector_inventory_observed_spoolman_service_id
AFTER INSERT OR UPDATE OF snapshot ON farm.connector_inventory_snapshots
FOR EACH ROW EXECUTE FUNCTION farm.record_observed_spoolman_service_id();

-- Settings rows are locked first: FOR SHARE cannot cover the nullable side of
-- the outer join, and a Connector may have no settings row at all.
CREATE OR REPLACE FUNCTION farm.lock_physical_spool_observations_with_receipt(p_farm_id uuid, p_service_id uuid)
RETURNS TABLE (agent_id uuid, observed_at bigint, snapshot jsonb, received_at bigint)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
#variable_conflict use_column
BEGIN
  PERFORM 1 FROM farm.spoolman_connector_settings c
  WHERE c.farm_id = p_farm_id ORDER BY c.agent_id FOR SHARE;
  -- A new statement, so a settings change waited on above is visible here.
  RETURN QUERY
  SELECT e.agent_id, s.observed_at, s.snapshot, s.received_at
  FROM farm.connector_enrollments e
  JOIN farm.connector_inventory_snapshots s
    ON s.farm_id = e.farm_id AND s.agent_id = e.agent_id
  LEFT JOIN farm.spoolman_connector_settings c
    ON c.farm_id = e.farm_id AND c.agent_id = e.agent_id
  WHERE e.farm_id = p_farm_id AND e.status = 'approved'
    AND (c.agent_id IS NULL OR c.configured)
    AND COALESCE(c.service_id::text, lower(s.snapshot->>'serviceId')) = p_service_id::text
  ORDER BY e.agent_id
  FOR SHARE OF e, s;
END;
$$;

CREATE OR REPLACE FUNCTION farm.read_physical_spool_observations_with_receipt(p_farm_id uuid, p_service_id uuid)
RETURNS TABLE (agent_id uuid, observed_at bigint, snapshot jsonb, received_at bigint)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
  SELECT e.agent_id, s.observed_at, s.snapshot, s.received_at
  FROM farm.connector_enrollments e
  JOIN farm.connector_inventory_snapshots s
    ON s.farm_id = e.farm_id AND s.agent_id = e.agent_id
  LEFT JOIN farm.spoolman_connector_settings c
    ON c.farm_id = e.farm_id AND c.agent_id = e.agent_id
  WHERE e.farm_id = p_farm_id AND e.status = 'approved'
    AND (c.agent_id IS NULL OR c.configured)
    AND COALESCE(c.service_id::text, lower(s.snapshot->>'serviceId')) = p_service_id::text
  ORDER BY e.agent_id
$$;
